def test_field_filter_license():
    """Test that field filter with 'license' only shows license field"""
    graph = {"nodes": {
        "1": {"ref": "lib/1.0@user/channel", "id": "1", "name": "lib", "version": "1.0", 
              "license": "MIT", "author": "Test Author", "description": "A test library"}
    }}

