def _check_cppstd_fixed(conanfile, cppstd, comparator, gnu_extensions):
    """ Fixed version with corrected comparison logic """
    if not str(cppstd).isdigit():
        raise Exception("cppstd parameter must be a number")

    def compare(lhs, rhs, comp):
        def extract_cpp_version(_cppstd):
            return str(_cppstd).replace("gnu", "")

        def add_millennium(_cppstd):
            return "19%s" % _cppstd if _cppstd == "98" else "20%s" % _cppstd

        lhs = add_millennium(extract_cpp_version(lhs))
        rhs = add_millennium(extract_cpp_version(rhs))
        return comp(lhs, rhs)  # Fixed: removed 'not'

    current_cppstd = "14"  # Test value
    if not compare(current_cppstd, cppstd, comparator):
        raise ConanInvalidConfiguration(
            "Current cppstd ({}) is {} than the required C++ standard ({}).".format(
                current_cppstd, "higher" if comparator == operator.gt else "lower", cppstd))

def test_comparison():
    # Test case 1: current=14, required=17, comparator=lt (check_min_cppstd)
    # Expected: should raise error because 14 < 17
    try:
        _check_cppstd_fixed(None, "17", operator.lt, False)
        print("Test 1: FAILED - should have raised error")
